const updateTheatreCase = `-- name: UpdateTheatreCase :execrows
UPDATE theatre.case
SET diagnosis_code = $1,
    diagnosis_display = $2,
    laterality = $3,
    site = $4,
    urgency = $5,
    expected_duration_seconds = $6,
    surgeon_id = $7,
    team = $8,
    requirements = $9,
    anaesthesia_type = $10,
    special_notes = $11,
    status = $12,
    room_id = $13::uuid,
    scheduled_start = $14::timestamptz,
    scheduled_end = $15::timestamptz,
    outcome = $16,
    outcome_reason = $17,
    outcome_note = $18,
    outcome_at = $19::timestamptz,
    updated_at = $20,
    version = version + 1
WHERE tenant_id = $21
  AND case_id = $22
  AND version = $23
`

type UpdateTheatreCaseParams struct {
	DiagnosisCode           string
	DiagnosisDisplay        string
	Laterality              string
	Site                    string
	Urgency                 string
	ExpectedDurationSeconds int64
	SurgeonID               string
	Team                    []string
	Requirements            []string
	AnaesthesiaType         string
	SpecialNotes            string
	Status                  string
	RoomID                  pgtype.UUID
	ScheduledStart          pgtype.Timestamptz
	ScheduledEnd            pgtype.Timestamptz
	Outcome                 string
	OutcomeReason           string
	OutcomeNote             string
	OutcomeAt               pgtype.Timestamptz
	UpdatedAt               pgtype.Timestamptz
	TenantID                uuid.UUID
	CaseID                  uuid.UUID
	ExpectedVersion         int64
}

// Guarded on the version, so two schedulers booking the same slot do not both
// win.
func (q *Queries) UpdateTheatreCase(ctx context.Context, arg UpdateTheatreCaseParams) (int64, error) {
	result, err := q.db.Exec(ctx, updateTheatreCase,
		arg.DiagnosisCode,
		arg.DiagnosisDisplay,
		arg.Laterality,
		arg.Site,
		arg.Urgency,
		arg.ExpectedDurationSeconds,
		arg.SurgeonID,
		arg.Team,
		arg.Requirements,
		arg.AnaesthesiaType,
		arg.SpecialNotes,
		arg.Status,
		arg.RoomID,
		arg.ScheduledStart,
		arg.ScheduledEnd,
		arg.Outcome,
		arg.OutcomeReason,
		arg.OutcomeNote,
		arg.OutcomeAt,
		arg.UpdatedAt,
		arg.TenantID,
		arg.CaseID,
		arg.ExpectedVersion,
	)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

